_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 2 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 0
    fi
}

_choice_gid() {
    _helper_id_list group 3
}

_choice_interface() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    if command -v ip >/dev/null 2>&1; then
        ip -o link show 2>/dev/null | gawk -F': ' '{ sub(/@.*/, "", $2); print $2 }'
    elif [[ -d /sys/class/net ]]; then
        local path
        for path in /sys/class/net/*; do
            printf '%s\n' "${path##*/}"
        done
    elif command -v ifconfig >/dev/null 2>&1; then
        ifconfig -l 2>/dev/null | tr ' ' '\n'
    fi
}

_choice_signal() {
    command kill -l 2>/dev/null | gawk '{
        for (i = 1; i <= NF; i++) {
            if ($i ~ /^SIG[A-Z][A-Z0-9]*$/) print $i
            else if ($i ~ /^[A-Z][A-Z0-9]*$/) print "SIG" $i
        }
    }'
}

_choice_socket_owner() {
    _argc_util_mode_parts :
    if [[ "$argc__parts_len" -le 1 ]]; then
        compgen -u | _argc_util_transform suffix=: nospace
    else
        compgen -g
    fi
}

_choice_terminal_type() {
    if command -v toe >/dev/null 2>&1; then
        toe -a 2>/dev/null | gawk -F'\t' '
            NF >= 2 { sub(/[ \t]+$/, "", $1); print $1 "\t" $2; next }
            { sub(/[ \t]+$/, ""); if ($0 != "") print }
        '
        return 0
    fi
    printf '%s\n' xterm-256color xterm screen-256color tmux-256color vt100 linux ansi
}

_choice_uid() {
    _helper_id_list passwd 3
}

_helper_id_list() {
    local db="$1" col="$2"
    if command -v getent >/dev/null 2>&1; then
        getent "$db" | gawk -F: -v col="$col" 'NF >= col { print $col "\t" $1 }'
    elif [[ -r "/etc/$db" ]]; then
        gawk -F: -v col="$col" 'NF >= col { print $col "\t" $1 }' "/etc/$db"
    fi
}
